  const beginInteraction=kind=>guard('切换工具',()=>{setTool('select');setPoints([]);setInteraction({kind,phase:['measure','paste'].includes(kind)||selection.length?'points':'selection',points:[]});setInspectorOpen(false);log(`${kind==='measure'?'测量':TRANSFORMS[kind]||kind}：${selection.length||['measure','paste'].includes(kind)?'指定第一点':'选择对象后按 Enter'}`)})
  const completeCorner=kind=>{try{if(constraints.some(c=>c.entities.some(id=>selection.includes(id))))throw new Error('所选图元受约束控制，请先解除约束');operate(cadCornerOperations(selected,fields.offset,kind==='chamfer'),{onSuccess:()=>setInteraction(null)})}catch(e){setError(e.message)}}
