      if(constraints.some(c=>c.entities.some(id=>selection.includes(id)))&&!['copy','mirror'].includes(kind))throw new Error('所选图元受约束控制，请先解除约束或修改约束尺寸')
      if(['copy','mirror'].includes(kind)){if(selected.some(e=>!e.editable||e.type==='DIMENSION'))throw new Error('请选择基础可编辑图元');add(selected.map(e=>kind==='mirror'?cadMirror(e,a,b):transformEntity(e,{translation:[b[0]-a[0],b[1]-a[1]]})),{onSuccess:()=>setInteraction(null)});return}
      if(kind==='stretch'){const ops=selected.map(e=>{if(!['LINE','LWPOLYLINE'].includes(e.type))throw new Error('端点拉伸支持直线和多段线');const points=e.type==='LINE'?[e.start,e.end]:e.points;let nearest=0;for(let i=1;i<points.length;i++)if(Math.hypot(points[i][0]-a[0],points[i][1]-a[1])<Math.hypot(points[nearest][0]-a[0],points[nearest][1]-a[1]))nearest=i;const moved=[points[nearest][0]+b[0]-a[0],points[nearest][1]+b[1]-a[1],points[nearest][2]||0];return {op:'update',id:e.id,changes:e.type==='LINE'?{[nearest?'end':'start']:moved}:{points:points.map((p,i)=>i===nearest?moved:p)}}});operate(ops,{onSuccess:()=>setInteraction(null)});return}
