    if(id==='import'){root.current?.querySelector('input[type=file]')?.click();return}
    if(id==='export'){exportDoc('dxf');return}if(id==='autoBubbles'){autoBubbles();return}
    if(id==='array'||id==='offset'){setTransformKind(id);showPanel('变换');return}
    if(id==='currentLayer'){if(selected.length!==1){setError('请先选择一个图元');return}setLayer(selected[0].layer);return}
    if(id==='restoreLayers'){operate(doc.layers.filter(l=>!l.visible||l.frozen).map(l=>({op:'layer',name:l.name,visible:true,frozen:false})));return}
    if(id==='ungroup'){const groups=doc.groups?.filter(g=>g.ids.some(id=>selection.includes(id)))||[];if(!groups.length){setError('请先选择组内图元');return}operate(groups.map(g=>({op:'ungroup',name:g.name})));return}
    if(id==='group'){if(selection.length<2){setError('请至少选择两个图元后创建组');return}operate([{op:'group',ids:selection}],{onSuccess:()=>log('已创建图元组')});return}
